feed:
  {{ site_name }} — {{ chain.label }} incidents
  Outages, reorgs, forks and stalls, as observed from one vantage point.
  tag:{{ tag_host }},2026:{{ chain.value }}/incidents


  {{ updated | rfc3339 }}
  {{ site_name }}
{% for e in events %}

    tag:{{ tag_host }},2026:{{ chain.value }}/event/{{ e.id }}
    {% if e.kind.value != 'reorg' and not e.ongoing %}Resolved: {% endif %}{{ e.kind | event_label }} — {{ e.subject }}

    {{ e.started_at | rfc3339 }}
    {{ (e.ended_at or e.started_at) | rfc3339 }}


    {% if e.detail %}{{ e.detail }}. {% endif %}Started {{ e.started_at | when }}{% if e.kind.value == 'reorg' %}.{% elif e.ongoing %}, ongoing.{% else %}, ended {{ e.ended_at | when }} after {{ e.duration_s | duration }}.{% endif %}

{% endfor %}
